/* Validated model providers may be connected without promoting observations into density. */
const validProvider=p=>p&&p.id&&p.version&&p.source&&p.validation?.status==='independently-reviewed'&&typeof p.sample==='function';
export class EcologicalModelRegistry{
  constructor({environmentalDataService=null,observationDataService=null}={}){this.dataContext={environmentalDataService,observationDataService};this.habitats=new Map();this.traffic=null;this.speedRisk=null;this.bathymetry=null;this.restrictions=null;}
  registerHabitat(speciesId,provider){if(!validProvider(provider)||!provider.predictors?.length||!provider.validation.spatialHoldout||!provider.validation.temporalHoldout||!/^[a-f0-9]{64}$/.test(provider.fitProvenance?.trainingSha256||'')||!['relative-habitat-suitability','calibrated-occurrence-probability'].includes(provider.outputType)||provider.outputType==='calibrated-occurrence-probability'&&!provider.validation.calibration)throw Error('reviewed_fitted_species_model_required');if(this.habitats.has(speciesId))throw Error('model_version_already_registered');this.habitats.set(speciesId,provider);}
  registerTrafficExposure(provider){if(!validProvider(provider)||provider.outputType!=='relative-traffic-exposure')throw Error('reviewed_traffic_exposure_model_required');this.traffic=provider;}
  registerSpeedRisk(provider){if(!validProvider(provider)||provider.outputType!=='relative-speed-risk-factor')throw Error('documented_speed_risk_model_required');this.speedRisk=provider;}
  async habitatExposure(speciesId,samples){const provider=this.habitats.get(speciesId);if(!provider)return {status:'unavailable',value:null,reason:'reviewed_species_habitat_model_missing',speciesId,outputType:'relative-habitat-exposure'};let weighted=0,coveredNM=0,highNM=0,totalNM=0;for(const sample of samples){if(!Number.isFinite(sample.distanceNM)||sample.distanceNM<0)throw Error('invalid_exposure_distance');totalNM+=sample.distanceNM;const r=await provider.sample(sample,this.dataContext);if(r?.status!=='available'||!Number.isFinite(r.value)||r.value<0||r.value>1)continue;weighted+=r.value*sample.distanceNM;coveredNM+=sample.distanceNM;if(Number.isFinite(provider.highSuitabilityThreshold)&&r.value>=provider.highSuitabilityThreshold)highNM+=sample.distanceNM;}return {status:Math.abs(totalNM-coveredNM)<1e-7?'computed':'partial_coverage',value:Math.abs(totalNM-coveredNM)<1e-7&&totalNM>0?weighted/totalNM:null,coveredMean:coveredNM?weighted/coveredNM:null,coveredNM,totalNM,highSuitabilityNM:Number.isFinite(provider.highSuitabilityThreshold)?highNM:null,speciesId,outputType:'relative-habitat-exposure',source:provider.source,modelId:provider.id,modelVersion:provider.version,validation:provider.validation};}
  async collisionExposure(speciesId,samples,{trafficProvider=this.traffic}={}){if(!this.habitats.has(speciesId)||!trafficProvider||!this.speedRisk)return {status:'unavailable',value:null,reason:'reviewed_habitat_traffic_speed_model_required',speciesId,interpretation:'relative_exposure_not_collision_probability'};let sum=0,total=0;for(const s of samples){const [h,t,v]=await Promise.all([this.habitats.get(speciesId).sample(s,this.dataContext),trafficProvider.sample(s,this.dataContext),this.speedRisk.sample(s,this.dataContext)]);if([h,t,v].some(r=>r?.status!=='available'||!Number.isFinite(r.value)||r.value<0))return {status:'unavailable',value:null,reason:'collision_inputs_incomplete',speciesId};sum+=h.value*t.value*v.value*s.distanceNM;total+=s.distanceNM;}return {status:total?'computed':'unavailable',value:total?sum/total:null,speciesId,interpretation:'relative_exposure_not_collision_probability',sourceVersions:[this.habitats.get(speciesId).version,trafficProvider.version,this.speedRisk.version]};}
  navigationReadiness(){return {landMask:true,bathymetry:!!this.bathymetry,verifiedRestrictions:!!this.restrictions,operationallyCleared:false,reason:'cartographic_land_avoidance_does_not_verify_draft_depth_tides_ice_or_regulations'};}
}
